// === Tab: mySketch ===
let sdf 
OPC.slider({ name: 'cutoff', label: 'Cutoff', min: 0, max: 1, step: 0.01, value: 0.5 })
OPC.slider({ name: 'dimple', label: 'Dimple', min: 0, max: 1, step: 0.01, value: 0.6 })
OPC.slider({ name: 'smoothness', label: 'Smoothness', min: 0, max: 1, step: 0.01, value: 0.25 })
let spheremap

function preload() {
	spheremap = loadImage('https://openprocessing.org/sketch/193534/files/narthex_equirect.jpg')
}

function setup() {
  createCanvas(4/3*window.innerHeight, window.innerHeight, WEBGL)

	// `createShaderPark` takes in a function that defines a shape using
	// the Shader Park API available here:
	// https://docs.shaderpark.com/references-js/
	// shaderParkCode is loaded in from shaderParkCode.js
	// Shader Park will convert the javascript into a shader for you
  sdf = createShaderPark(
		function() {
			let getCutoff = glslFunc(`
			float getCutoff() {
			  return cutoff;
			}
			`)
			let getDimple = glslFunc(`
			float getDimple() {
			  return dimple;
			}
			`)
			let getSmoothness = glslFunc(`
			float getSmoothness() {
			  return smoothness;
			}
			`)

			function smoothUnion(d1, d2, k) {
				let h = clamp(0.5 + 0.5*(d2-d1)/k, 0, 1)
				return mix(d2, d1, h) - k*h*(1-h)
			}

			function smoothSubtract(d1, d2, k) {
				var h = clamp(0.5 - 0.5*(d2+d1)/k, 0, 1)
				return mix(d2, -d1, h) + k*h*(1.0-h)
			}

			function smoothIntersection(d1, d2, k) {
				var h = clamp(0.5 - 0.5*(d2-d1)/k, 0, 1);
				return mix(d2, d1, h) + k*h*(1.0-h);
			}

			let sdfPlane = glslSDF(`
			//https://iquilezles.org/articles/distfunctions/
			float sdfPlane( vec3 p, vec3 n, float h )
			{
				// n must be normalized
				return dot(p,n) + h;
			}`)

			let sdfCapsule = glslSDF(`
			float sdfCapsule( vec3 p, vec3 a, vec3 b, float r )
			{
				vec3 pa = p - a, ba = b - a;
				float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
				return length( pa - ba*h ) - r;
			}`)

			const mainSphere = extractSDF(shape(() => {
				sphere(0.5)
			}))
			const cutoffHeight = () => mix(-1, 0.5, getCutoff())
			const cutBottom = extractSDF(shape(() => {
				sdfPlane(vec3(0,-1,0), cutoffHeight())
			}))
			const dimpleShape = extractSDF(shape(() => {
				const r = 0.1
				const dimpleHeight = mix(-1,1,getDimple())-r-getSmoothness()
				sdfCapsule(
					vec3(0,-5,0),
					vec3(0,dimpleHeight,0),
					r,
				)
				displace(0, cutoffHeight() + dimpleHeight/2, 0)
				rotateX(PI/2)
				blend(getSmoothness())
				cylinder(0.2, 5)
			}))

			color(0,0,0)
			setSpace(getSpace() * vec3(0.75, 0.75, 1))
			let d = mainSphere()
			d = smoothIntersection(d, cutBottom(), getSmoothness())
			d = smoothSubtract(dimpleShape(), d, getSmoothness())
			setSDF(d)
		},
		{
			scale: 1.0, 
			drawGeometry: () => sphere(400)
		}
	);

	sdf.shader._fragSrc = sdf.shader._fragSrc.replace(
		'precision highp float;',
		`precision highp float;
		uniform float cutoff;
		uniform float dimple;
		uniform float smoothness;
		uniform sampler2D spheremap;
		`
	).replace(
		'outputColor = col.color;',
		`
		vec3 n = normalize((uModelViewMatrix * vec4(normal, 0.)).xyz);
		float phi = acos( n.y );
		float theta = 0.0;
		theta = acos(n.x / sin(phi));
		float sinTheta = n.z / sin(phi);
		if (sinTheta < 0.0) {
			// Turn it into -theta, but in the 0-2PI range
			theta = 2.0 * PI - theta;
		}
		theta = theta / (2.0 * 3.14159);
		phi = phi / 3.14159 ;
		vec2 angles = vec2( fract(theta + 0.25), 1.0 - phi );

		outputColor = texture(spheremap, angles).xyz + col.color;
		`
	)
}

function draw() {
  background(0)
  orbitControl()
	scale(1.2)

	// The Shader Park distance field is drawn to an invisible sphere.
	// A good practice is to keep your coordinate space in Shader Park
	// close to (0, 0, 0) and then move the sdf around later on with P5
	scale(1, -1, 1)
	sdf.shader.setUniform('cutoff', cutoff)
	sdf.shader.setUniform('dimple', dimple)
	sdf.shader.setUniform('smoothness', smoothness)
	sdf.shader.setUniform('spheremap', spheremap)
  sdf.draw()
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

